373→/**
374→ * @param {string} repoRoot
375→ * @param {string} label
376→ * @param {string} sha
377→ * @param {{log?: object, dependencyDirs?: string[], sparsePaths?: string[]}} [opts]
378→ * @returns {Promise<{dir:string, sha:string, copiedDependencies:string[], sparsePaths:string[], cleanup:() => Promise<void>}>}
379→ * @throws {InvalidShaError}
380→ */
381→export async function freshVerifySandbox(repoRoot, label, sha, opts = {}) {
382→  let fullSha;
383→  try {
384→    fullSha = sh('git', ['rev-parse', '--verify', `${sha}^{commit}`], repoRoot);
385→  } catch {
386→    throw new InvalidShaError(`freshVerifySandbox: "${sha}" does not resolve to a commit in ${repoRoot}`);
387→  }
388→  // Validate every source before registering a worktree. Invalid configuration therefore cannot
389→  // create a detached checkout that no caller has a cleanup handle for.
390→  const sources = dependencySources(repoRoot, opts.dependencyDirs ?? []);
391→  const sparsePaths = sparseProjection(opts.sparsePaths ?? []);
392→
393→  const verifyRoot = join(repoRoot, '.baton', 'verify');
394→  mkdirSync(verifyRoot, { recursive: true });
395→  const suffix = randomBytes(4).toString('hex');
396→  const dir = join(verifyRoot, `${label}-${suffix}`);
397→  let registered = false;
398→
399→  const cleanup = async () => {
400→    if (registered || existsSync(dir)) {
401→      try {
402→        sh('git', ['worktree', 'remove', '--force', dir], repoRoot);
403→      } catch {
404→        rmSync(dir, { recursive: true, force: true });
405→      }
406→    }
407→    try { sh('git', ['worktree', 'prune'], repoRoot); } catch { /* best-effort */ }
408→  };
409→
410→  // Source stays commit-fresh while explicitly configured installed dependencies are copied into
411→  // the sandbox. Never symlink/hardlink the main checkout: the pinned verification command must
412→  // not be able to mutate the orchestrator's toolchain through its dependency path. Any copy
413→  // failure removes and prunes the worktree before the error escapes.
414→  const copiedDependencies = [];
415→  try {
416→    sh('git', ['worktree', 'add', '--detach', ...(sparsePaths.length ? ['--no-checkout'] : []), dir, fullSha], repoRoot);
417→    registered = true;
418→    if (sparsePaths.length) {
419→      gitFile(['sparse-checkout', 'set', '--no-cone', '--stdin'], dir, { input: `${sparsePaths.map((path) => `/${path}`).join('\n')}\n`, encoding: 'utf8' });
420→      gitFile(['checkout', '--detach', fullSha], dir, { stdio: 'pipe' });
421→    }
422→    copiedDependencies.push(...materializeDependencies(dir, sources));
423→  } catch (err) {
424→    await cleanup();
425→    throw err;
426→  }
427→
428→  logEvent(opts, 'worktree', 'worktree.verify_sandbox_created', { dir, sha: fullSha, label, copiedDependencies, sparsePaths });
429→  return { dir, sha: fullSha, copiedDependencies, sparsePaths, cleanup };
430→}
