483→/**
484→ * @param {string} repoRoot
485→ * @param {string[]} expectedActiveTaskIds
486→ * @param {{log?: object}} [opts]
487→ * @returns {Promise<{prunedAdminEntries:string[], removedZombieDirs:string[], removedIntegrationDirs:string[], errors:string[]}>}
488→ */
489→export async function reconcile(repoRoot, expectedActiveTaskIds = [], opts = {}) {
490→  const report = { prunedAdminEntries: [], removedZombieDirs: [], removedIntegrationDirs: [], errors: [] };
491→  try {
492→    sh('git', ['worktree', 'prune'], repoRoot);
493→  } catch (err) {
494→    report.errors.push(`prune: ${err.message || err}`);
495→  }
496→
497→  // Structured integration is never resumed after coordinator restart: without an in-memory
498→  // operation holding the freshly observed verification verdict, a candidate is evidence only.
499→  // Reap every detached stage and require a new attempt to reconstruct and reverify it.
500→  const mergeRoot = integrationRoot(repoRoot);
501→  if (existsSync(mergeRoot)) {
502→    for (const entry of readdirSync(mergeRoot)) {
503→      const fullDir = join(mergeRoot, entry);
504→      let isDir = false; try { isDir = statSync(fullDir).isDirectory(); } catch { continue; }
505→      if (!isDir) continue;
506→      try {
507→        try { sh('git', ['worktree', 'remove', '--force', fullDir], repoRoot); }
508→        catch { rmSync(fullDir, { recursive: true, force: true }); }
509→        report.removedIntegrationDirs.push(fullDir);
510→        logEvent(opts, entry, 'worktree.integration_reconciled', { dir: fullDir });
511→      } catch (err) { report.errors.push(`${entry}: ${err.message || err}`); }
512→    }
513→    try { if (readdirSync(mergeRoot).length === 0) rmSync(mergeRoot, { recursive: true, force: true }); } catch { /* best effort */ }
514→  }
515→
516→  const expected = new Set(expectedActiveTaskIds);
517→
518→  const wtRoot = join(repoRoot, '.baton', 'wt');
519→  if (existsSync(wtRoot)) {
520→    for (const entry of readdirSync(wtRoot)) {
521→      if (entry.endsWith('.meta.json')) continue;
522→      const fullDir = join(wtRoot, entry);
523→      let isDir = false;
524→      try { isDir = statSync(fullDir).isDirectory(); } catch { continue; }
525→      if (!isDir) continue;
526→      if (expected.has(entry)) continue;
527→      try {
528→        try {
529→          sh('git', ['worktree', 'remove', '--force', fullDir], repoRoot);
530→        } catch {
531→          rmSync(fullDir, { recursive: true, force: true });
532→        }
533→        const metaFile = metaPathFor(repoRoot, entry);
534→        if (existsSync(metaFile)) rmSync(metaFile, { force: true });
535→        report.removedZombieDirs.push(fullDir);
536→        logEvent(opts, entry, 'worktree.reconciled', { dir: fullDir });
537→      } catch (err) {
538→        report.errors.push(`${entry}: ${err.message || err}`);
539→      }
540→    }
541→  }
542→
543→  // Note: `.baton/verify/*` sandboxes are intentionally NOT swept here. They are always
544→  // created and reaped synchronously by their own caller (referee/coordinator via
545→  // `sandbox.cleanup()`) within the same operation, so they never need boot-time zombie
546→  // detection, and sweeping them here would misattribute reconcile events away from the
547→  // taskId-scoped `worker` field callers rely on (red workers-trust#9).
548→  try { sh('git', ['worktree', 'prune'], repoRoot); } catch { /* best-effort */ }
549→  return report;
550→}
